    qkd_land_pc u_pc29 (.ck(ck_p[29]), .rst_n(rst_n), .lpc(5'd15), .li(li29), .lp(lp29), .cf(cf29), .gw(gw[29]), .gc(gc[29]), .es(es29), .er(er29), .dni(dn[30]), .dno(dn[29]), .upi(up[29]), .upo(up[30]), .cri(cr[29]), .cro(cr[30]), .fi(pf[29]), .fo(pf[30]));
    qkd_land_pc u_pc30 (.ck(ck_p[30]), .rst_n(rst_n), .lpc(5'd23), .li(li30), .lp(lp30), .cf(cf30), .gw(gw[30]), .gc(gc[30]), .es(es30), .er(er30), .dni(dn[31]), .dno(dn[30]), .upi(up[30]), .upo(up[31]), .cri(cr[30]), .cro(cr[31]), .fi(pf[30]), .fo(pf[31]));
    qkd_land_pc u_pc31 (.ck(ck_p[31]), .rst_n(rst_n), .lpc(5'd31), .li(li31), .lp(lp31), .cf(cf31), .gw(gw[31]), .gc(gc[31]), .es(es31), .er(er31), .dni(dn[32]), .dno(dn[31]), .upi(up[31]), .upo(up[32]), .cri(cr[31]), .cro(cr[32]), .fi(pf[31]), .fo(pf[32]));
    qkd_land_grp_epoch u_g0 (.ck(ck_g[0]), .rst_n(rst_n), .g(3'd4), .s(st), .gw0(gw[0]), .gc0(gc[0]), .gw1(gw[1]), .gc1(gc[1]), .gw2(gw[2]), .gc2(gc[2]), .gw3(gw[3]), .gc3(gc[3]), .rq(rq4), .rs(rs4), .lt(tap[0][1067:1047]), .kn(tap[0][1046:0]), .fi(gf[0]), .fo(gf[1]));
    qkd_land_grp_epoch u_g1 (.ck(ck_g[1]), .rst_n(rst_n), .g(3'd5), .s(st), .gw0(gw[4]), .gc0(gc[4]), .gw1(gw[5]), .gc1(gc[5]), .gw2(gw[6]), .gc2(gc[6]), .gw3(gw[7]), .gc3(gc[7]), .rq(rq5), .rs(rs5), .lt(tap[1][1067:1047]), .kn(tap[1][1046:0]), .fi(gf[1]), .fo(gf[2]));
    qkd_land_grp_epoch u_g2 (.ck(ck_g[2]), .rst_n(rst_n), .g(3'd0), .s(st), .gw0(gw[8]), .gc0(gc[8]), .gw1(gw[9]), .gc1(gc[9]), .gw2(gw[10]), .gc2(gc[10]), .gw3(gw[11]), .gc3(gc[11]), .rq(rq0), .rs(rs0), .lt(tap[2][1067:1047]), .kn(tap[2][1046:0]), .fi(gf[2]), .fo(gf[3]));
    qkd_land_grp_epoch u_g3 (.ck(ck_g[3]), .rst_n(rst_n), .g(3'd1), .s(st), .gw0(gw[12]), .gc0(gc[12]), .gw1(gw[13]), .gc1(gc[13]), .gw2(gw[14]), .gc2(gc[14]), .gw3(gw[15]), .gc3(gc[15]), .rq(rq1), .rs(rs1), .lt(tap[3][1067:1047]), .kn(tap[3][1046:0]), .fi(gf[3]), .fo(gf[4]));
    qkd_land_grp_epoch u_g4 (.ck(ck_g[4]), .rst_n(rst_n), .g(3'd2), .s(st), .gw0(gw[16]), .gc0(gc[16]), .gw1(gw[17]), .gc1(gc[17]), .gw2(gw[18]), .gc2(gc[18]), .gw3(gw[19]), .gc3(gc[19]), .rq(rq2), .rs(rs2), .lt(tap[4][1067:1047]), .kn(tap[4][1046:0]), .fi(gf[4]), .fo(gf[5]));
    qkd_land_grp_epoch u_g5 (.ck(ck_g[5]), .rst_n(rst_n), .g(3'd3), .s(st), .gw0(gw[20]), .gc0(gc[20]), .gw1(gw[21]), .gc1(gc[21]), .gw2(gw[22]), .gc2(gc[22]), .gw3(gw[23]), .gc3(gc[23]), .rq(rq3), .rs(rs3), .lt(tap[5][1067:1047]), .kn(tap[5][1046:0]), .fi(gf[5]), .fo(gf[6]));
    qkd_land_grp_epoch u_g6 (.ck(ck_g[6]), .rst_n(rst_n), .g(3'd6), .s(st), .gw0(gw[24]), .gc0(gc[24]), .gw1(gw[25]), .gc1(gc[25]), .gw2(gw[26]), .gc2(gc[26]), .gw3(gw[27]), .gc3(gc[27]), .rq(rq6), .rs(rs6), .lt(tap[6][1067:1047]), .kn(tap[6][1046:0]), .fi(gf[6]), .fo(gf[7]));
    qkd_land_grp_epoch u_g7 (.ck(ck_g[7]), .rst_n(rst_n), .g(3'd7), .s(st), .gw0(gw[28]), .gc0(gc[28]), .gw1(gw[29]), .gc1(gc[29]), .gw2(gw[30]), .gc2(gc[30]), .gw3(gw[31]), .gc3(gc[31]), .rq(rq7), .rs(rs7), .lt(tap[7][1067:1047]), .kn(tap[7][1046:0]), .fi(gf[7]), .fo(gf[8]));
    qkd_land_emb_ifw u_emb (.ck(ck_e), .rst_n(rst_n), .st(st), .emf(emf), .emf_cr(emf_cr), .emr(emr), .emr_cr(emr_cr), .dno(dn[32]), .upi(up[32]), .cri(cr[32]), .fi(pf[32]), .gfi(gf[8]), .mf(mf));
endmodule

module qkd_astk_strip_s #(
    parameter integer RL = 1
) (
    input  wire          ck_c,
    input  wire [3:0]    ck_z,
    input  wire [63:0]   ck_v,
    input  wire [31:0]   ck_x,
    input  wire [7:0]    ck_e,
    input  wire          ck_r,
    input  wire          rst_n,
    input  wire [1:0]    st,
    input  wire [539:0]  aq,
    input  wire [35:0]   am,
    output wire [562:0]  ap,
    output wire [1:0]    pv_done,
    output wire          af,
    output wire [20:0]   lt,
    input  wire [424:0]  so0,
    input  wire [424:0]  so1,
    input  wire [424:0]  so2,
    input  wire [424:0]  so3,
    input  wire [424:0]  so4,
    input  wire [424:0]  so5,
    input  wire [424:0]  so6,
    input  wire [424:0]  so7,
    output wire [633:0]  si0,
    output wire [633:0]  si1,
    output wire [633:0]  si2,
    output wire [633:0]  si3,
    output wire [633:0]  si4,
    output wire [633:0]  si5,
    output wire [633:0]  si6,
    output wire [633:0]  si7,
    input  wire [1023:0] nb0_0,
    input  wire [1023:0] nb0_1,
    input  wire [1023:0] nb0_2,
    input  wire [1023:0] nb0_3,
    input  wire [1023:0] nb1_0,
    input  wire [1023:0] nb1_1,
    input  wire [1023:0] nb1_2,
    input  wire [1023:0] nb1_3,
    input  wire [1023:0] nb2_0,
    input  wire [1023:0] nb2_1,
    input  wire [1023:0] nb2_2,
    input  wire [1023:0] nb2_3,
    input  wire [1023:0] nb3_0,
    input  wire [1023:0] nb3_1,
    input  wire [1023:0] nb3_2,
    input  wire [1023:0] nb3_3,
    input  wire [1023:0] nb4_0,
    input  wire [1023:0] nb4_1,
    input  wire [1023:0] nb4_2,
    input  wire [1023:0] nb4_3,
    input  wire [1023:0] nb5_0,
    input  wire [1023:0] nb5_1,
    input  wire [1023:0] nb5_2,
    input  wire [1023:0] nb5_3,
    input  wire [1023:0] nb6_0,
    input  wire [1023:0] nb6_1,
    input  wire [1023:0] nb6_2,
    input  wire [1023:0] nb6_3,
    input  wire [1023:0] nb7_0,
    input  wire [1023:0] nb7_1,
    input  wire [1023:0] nb7_2,
    input  wire [1023:0] nb7_3
);
    localparam integer HD = 128;
    localparam integer NS = 52;                    // lane stations a column: 4 rows x (8 tree cells + ep + 4 ex)
    wire [1:0] SS = st;
    wire [425*8-1:0]  so_f = {so7, so6, so5, so4, so3, so2, so1, so0};
    wire [634*8-1:0]  si_f;
    assign si0 = si_f[634*0 +: 634];
    assign si1 = si_f[634*1 +: 634];
    assign si2 = si_f[634*2 +: 634];
    assign si3 = si_f[634*3 +: 634];
    assign si4 = si_f[634*4 +: 634];
    assign si5 = si_f[634*5 +: 634];
    assign si6 = si_f[634*6 +: 634];
    assign si7 = si_f[634*7 +: 634];
    wire [4096*8-1:0] nb_f = {nb7_3, nb7_2, nb7_1, nb7_0, nb6_3, nb6_2, nb6_1, nb6_0, nb5_3, nb5_2, nb5_1, nb5_0, nb4_3, nb4_2, nb4_1, nb4_0, nb3_3, nb3_2, nb3_1, nb3_0, nb2_3, nb2_2, nb2_1, nb2_0, nb1_3, nb1_2, nb1_1, nb1_0, nb0_3, nb0_2, nb0_1, nb0_0};
    // ---- the port --------------------------------------------------------------------------------------------------------
    wire [571:0] cq_o;
    wire [266:0] cx_i;
    wire [5:0]   cco;
    wire [262:0] px, py;
    wire [137:0] czi;
    wire         cfx, cfy, cfz;
    wire [564:0] ap_w;
    qkd_astk_ctl_tp8 u_ctl (.ck(ck_c), .rst_n(rst_n), .st(SS), .aq(aq), .lt(lt),
        .am(am), .ap(ap_w), .af(af), .qo(cq_o), .xi(cx_i), .co(cco), .px(px), .py(py),
        .zi(czi), .fx(cfx), .fy(cfy), .fz(cfz));
    // die ap word (563 b) = the hub ap_<st> fields {si 43 | pi 520}: ap_w without the P.V done pair [44:43]
    assign ap = {ap_w[564:45], ap_w[42:0]}; assign pv_done = ap_w[44:43];
    // ---- engines and their slices -------------------------------------------------------------------------------------
    wire [424:0]  so_w [0:7];
    wire [633:0]  si_w [0:7];
    wire [4095:0] nb_w [0:7];
    wire [571:0]  qi_w [0:8];                      // the command bus: qi_w[8] at the port, one relay hop a slice downwards
    wire [266:0]  xo_w [0:8];                      // xo_w[0] = 0; slice j takes xo_w[j], gives xo_w[j + 1]
    wire [650:0]  zo_w [0:8];
    wire [521:0]  ro_w [0:8];                      // the e-row bus: ro_w[8] = slice 7's zo, one relay hop a slice downwards
    wire [7:0]    cr_w;
    assign xo_w[0] = 267'd0; assign zo_w[0] = 651'd0;
    qkd_srly #(.W(572), .D(RL)) u_rq8 (.clk(ck_r), .rst_n(rst_n), .d(cq_o), .q(qi_w[8]));
    qkd_srly #(.W(267), .D(RL)) u_rx8 (.clk(ck_r), .rst_n(rst_n), .d(xo_w[8]), .q(cx_i));
    assign ro_w[8] = {zo_w[8][650:139], zo_w[8][10:7], zo_w[8][6:3], zo_w[8][2], zo_w[8][0]};
    // lanes: column c, station s (bottom to top)
    wire [535:0] U [0:1][0:NS];
    wire [535:0] D [0:1][0:NS];
    wire [262:0] P [0:1][0:NS];
    wire [5:0]   C [0:1][0:NS];
    wire         TU [0:1][0:NS];
    wire         TD [0:1][0:NS];
    wire         F [0:1][0:NS];
    wire [3:0]   KU [0:1][0:NS];                   // up-lane credits (travel down)
    wire [3:0]   KD [0:1][0:NS];                   // down-lane credits (travel up)
    genvar c, r, e, hp, z;
    generate for (c = 0; c < 2; c = c + 1) begin : g_end
        assign U[c][0] = 536'd0; assign P[c][0] = 263'd0; assign TU[c][0] = 1'b0; assign F[c][0] = 1'b0;
        assign D[c][NS] = 536'd0; assign TD[c][NS] = 1'b0; assign KU[c][NS] = 4'd0; assign KD[c][0] = 4'd0;
        qkd_srly #(.W(6), .D(RL)) u_rc (.clk(ck_r), .rst_n(rst_n), .d(cco), .q(C[c][NS]));
    end endgenerate
    qkd_srly #(.W(263), .D(RL)) u_rpx (.clk(ck_r), .rst_n(rst_n), .d(P[0][NS]), .q(px));
    qkd_srly #(.W(263), .D(RL)) u_rpy (.clk(ck_r), .rst_n(rst_n), .d(P[1][NS]), .q(py));
    qkd_srly #(.W(2), .D(RL)) u_rf (.clk(ck_r), .rst_n(rst_n), .d({F[1][NS], F[0][NS]}), .q({cfy, cfx}));
    generate for (e = 0; e < 8; e = e + 1) begin : g_e
        localparam integer EC = e % 2;                                // the engine's column
        localparam integer ST = 13 * (e / 2) + 6;                     // its ep station; ex leaves at ST - 2, ST - 1, ST + 1, ST + 2
        assign so_w[e] = so_f[425*e +: 425]; assign si_f[634*e +: 634] = si_w[e]; assign nb_w[e] = nb_f[4096*e +: 4096];
        wire [266:0] xo_e, xi_e;
        wire [650:0] zo_e, zi_e;
        wire [263:0] xa;
        wire [135:0] xe;
        qkd_srly #(.W(267), .D(RL)) u_rx (.clk(ck_r), .rst_n(rst_n), .d(xo_w[e]), .q(xi_e));
        qkd_srly #(.W(651), .D((e % 2) ? 0 : RL)) u_rz (.clk(ck_r), .rst_n(rst_n), .d(zo_w[e]), .q(zi_e));
        qkd_srly #(.W(572), .D(RL)) u_rq (.clk(ck_r), .rst_n(rst_n), .d(qi_w[e + 1]), .q(qi_w[e]));
        qkd_srly #(.W(522), .D(RL)) u_rr (.clk(ck_r), .rst_n(rst_n), .d(ro_w[e + 1]), .q(ro_w[e]));
        qkd_astk_ep u_ep (.ck(ck_e[e]), .rst_n(rst_n), .sq({SS, 3'(e)}), .so(so_w[e]), .si(si_w[e]), .qi(qi_w[e]),
            .xi(xi_e), .xo(xo_e), .zi(zi_e), .zo(zo_e), .ri(ro_w[e]), .xa(xa), .xe(xe), .cr(cr_w[e]),
            .ui(U[EC][ST]), .uo(U[EC][ST+1]), .di(D[EC][ST+1]), .do_(D[EC][ST]), .pi(P[EC][ST]), .po(P[EC][ST+1]),
            .ci(C[EC][ST+1]), .co(C[EC][ST]), .tui(TU[EC][ST]), .tuo(TU[EC][ST+1]), .tdi(TD[EC][ST+1]), .tdo(TD[EC][ST]),
            .kui(KU[EC][ST+1]), .kuo(KU[EC][ST]), .kdi(KD[EC][ST]), .kdo(KD[EC][ST+1]), .fi(F[EC][ST]), .fo(F[EC][ST+1]));
        genvar xh;
        for (xh = 0; xh < 4; xh = xh + 1) begin : g_x
            localparam integer XS = (xh < 2) ? ST - 2 + xh : ST - 1 + xh;
            qkd_astk_ex u_ex (.ck(ck_x[4*e+xh]), .rst_n(rst_n), .xa(xa[66*xh +: 66]), .xe(xe[34*xh +: 34]),
                .ui(U[EC][XS]), .uo(U[EC][XS+1]), .di(D[EC][XS+1]), .do_(D[EC][XS]), .pi(P[EC][XS]), .po(P[EC][XS+1]),
                .ci(C[EC][XS+1]), .co(C[EC][XS]), .tui(TU[EC][XS]), .tuo(TU[EC][XS+1]), .tdi(TD[EC][XS+1]), .tdo(TD[EC][XS]),
                .kui(KU[EC][XS+1]), .kuo(KU[EC][XS]), .kdi(KD[EC][XS]), .kdo(KD[EC][XS+1]), .fi(F[EC][XS]), .fo(F[EC][XS+1]));
        end
        // the other column's stations beside this slice: the other engine of the row fills them
        assign xo_w[e + 1] = xo_e; assign zo_w[e + 1] = zo_e;
    end endgenerate
    // ---- the tree cells ----------------------------------------------------------------------------------------------------
    wire [1:0] cra_w [0:3];                        // [row][column 0 only is used]
    wire [1:0] crb_w [0:3];
    generate for (r = 0; r < 4; r = r + 1) begin : g_r
        for (c = 0; c < 2; c = c + 1) begin : g_c
            wire [9:0] nco_w [0:3];
            wire [9:0] ndo_w [0:3];
            wire [3:0] cra_h, crb_h;
            for (hp = 0; hp < 4; hp = hp + 1) begin : g_h
                localparam integer ST = 13 * r + ((hp < 2) ? 2 * hp : 9 + 2 * (hp - 2));
                localparam integer FAR = (hp == 0 || hp == 3) ? 1 : 0;
                localparam integer NEAR = (hp == 0) ? 1 : 2;            // the cell the far one takes its control from
                // level-4 cell: the head's 16 kk slots of this column, kk = 4 (m / 2) + 2 c + m % 2
                wire [511:0] wa, wb;
                genvar m;
                for (m = 0; m < 16; m = m + 1) begin : g_m
                    assign wa[32*m +: 32] = nb_w[2*r][1024*hp + 32*(4*(m/2) + 2*c + (m%2)) +: 32];
                    assign wb[32*m +: 32] = nb_w[2*r+1][1024*hp + 32*(4*(m/2) + 2*c + (m%2)) +: 32];
                end
                wire [9:0] nc = FAR ? nco_w[NEAR] : so_w[2*r][421:412];
                wire [9:0] nd = FAR ? ndo_w[NEAR] : so_w[2*r+1][421:412];
                wire [133:0] lo_a, lo_b;
                wire         lc_b;                                  // the B cell's credit to the A cell below
                // A: y to the B cell above (rows 0, 2) or into the down lane (rows 1, 3)
                localparam [1:0] YM_A = (r == 1 || r == 3) ? 2'd2 : 2'd0;
                localparam [2:0] ATH_A = 2 * r, BTH_A = 2 * r + 1;
                qkd_astk_pv_tp8 u_a (.ck(ck_v[16*r+8*c+2*hp]), .rst_n(rst_n),
                    .cfg({1'b0, 1'(FAR), BTH_A, ATH_A, YM_A, 2'd0, 2'd0, 2'd0, 2'(hp)}),
                    .wa(wa), .wb(wb), .nc(nc), .nd(nd), .nco(nco_w[hp]), .ndo(ndo_w[hp]), .cra(cra_h[hp]), .crb(crb_h[hp]),
                    .li(134'd0), .lo(lo_a), .ui(U[c][ST]), .uo(U[c][ST+1]), .di(D[c][ST+1]), .do_(D[c][ST]),
                    .pi(P[c][ST]), .po(P[c][ST+1]), .ci(C[c][ST+1]), .co(C[c][ST]), .tui(TU[c][ST]), .tuo(TU[c][ST+1]),
                    .tdi(TD[c][ST+1]), .tdo(TD[c][ST]), .lci(lc_b), .lco(), .kui(KU[c][ST+1]), .kuo(KU[c][ST]), .kdi(KD[c][ST]),
                    .kdo(KD[c][ST+1]), .fi(F[c][ST]), .fo(F[c][ST+1]));
                // B: row 0 level 5 (a local, b down lane, y up); row 1 level 6 (a up, b down, y up);
                //    row 2 level 5 (a local, b down, y down); row 3 level 7 (up lane, the P.V lane)
                localparam [1:0] LVL_B = (r == 0 || r == 2) ? 2'd1 : (r == 1) ? 2'd2 : 2'd3;
                localparam [1:0] AM_B = (r == 0 || r == 2) ? 2'd0 : 2'd1;
                localparam [1:0] BM_B = (r == 3) ? 2'd0 : 2'd2;
                localparam [1:0] YM_B = (r == 0 || r == 1) ? 2'd1 : (r == 2) ? 2'd2 : 2'd0;
                localparam [2:0] ATH_B = (r == 2) ? 3'd4 : 3'd0;
                localparam [2:0] BTH_B = (r == 0) ? 3'd2 : (r == 1) ? 3'd4 : (r == 2) ? 3'd6 : 3'd0;
                qkd_astk_pv_tp8 u_b (.ck(ck_v[16*r+8*c+2*hp+1]), .rst_n(rst_n),
                    .cfg({1'b0, 1'b0, BTH_B, ATH_B, YM_B, BM_B, AM_B, LVL_B, 2'(hp)}),
                    .wa(512'd0), .wb(512'd0), .nc(10'd0), .nd(10'd0), .nco(), .ndo(), .cra(), .crb(),
                    .li(lo_a), .lo(lo_b), .ui(U[c][ST+1]), .uo(U[c][ST+2]), .di(D[c][ST+2]), .do_(D[c][ST+1]),
                    .pi(P[c][ST+1]), .po(P[c][ST+2]), .ci(C[c][ST+2]), .co(C[c][ST+1]), .tui(TU[c][ST+1]), .tuo(TU[c][ST+2]),
                    .tdi(TD[c][ST+2]), .tdo(TD[c][ST+1]), .lci(1'b0), .lco(lc_b), .kui(KU[c][ST+2]), .kuo(KU[c][ST+1]),
                    .kdi(KD[c][ST+1]), .kdo(KD[c][ST+2]), .fi(F[c][ST+1]), .fo(F[c][ST+2]));
            end
            if (c == 0) begin : g_cr
                assign cr_w[2*r] = cra_h[1]; assign cr_w[2*r+1] = crb_h[1];
            end
        end
    end endgenerate
    // ---- the Z tree behind slice 7 ------------------------------------------------------------------------------------------
    wire [137:0] zn_w [0:4];
    wire [4:0]   zf_w;
    assign zn_w[0] = {zo_w[8][138:11], zo_w[8][10:7], zo_w[8][6:3], zo_w[8][2], zo_w[8][0]};
    assign zf_w[0] = 1'b0;
